                ' . FILTER(?y = "carol") }'
            )
        )
        self.assertFalse(
            self.model.ask(
                'ASK WHERE { { ?x knows ?y } UNION { ?x likes ?y }'
                ' . FILTER(?y = "nobody") }'
            )
        )

